import React from 'react';
import { 
  LayoutDashboard, 
  Calendar, 
  BarChart3, 
  Trophy, 
  Settings, 
  Moon, 
  Sun,
  Flame,
  Zap,
  Target
} from 'lucide-react';
import { motion } from 'framer-motion';

interface SidebarProps {
  currentView: string;
  setCurrentView: (view: string) => void;
  darkMode: boolean;
  setDarkMode: (dark: boolean) => void;
  points: number;
  streak: number;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  currentView, 
  setCurrentView, 
  darkMode, 
  setDarkMode,
  points,
  streak
}) => {
  const menuItems = [
    { id: 'dashboard', label: "Dashboard", icon: LayoutDashboard },
    { id: 'calendar', label: "Calendar", icon: Calendar },
    { id: 'reports', label: "Analytics", icon: BarChart3 },
    { id: 'rewards', label: "Rewards", icon: Trophy },
    { id: 'settings', label: "Settings", icon: Settings },
  ];

  return (
    <aside className="w-80 glass border-r border-white/5 h-screen sticky top-0 flex flex-col p-8 z-50 overflow-hidden">
      <div className="absolute -top-20 -left-20 w-40 h-40 bg-blue-600/5 blur-3xl pointer-events-none" />

      <div className="flex items-center gap-4 px-2 mb-12 relative z-10">
        <motion.div 
          whileHover={{ rotate: 15, scale: 1.1 }}
          className="w-14 h-14 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-2xl flex items-center justify-center shadow-2xl shadow-blue-500/30 ring-4 ring-blue-500/10 cursor-pointer"
        >
          <Flame className="text-white fill-white animate-pulse" size={32} />
        </motion.div>
        <div>
          <h1 className="text-2xl font-black italic tracking-tighter leading-none text-white">180-ONE</h1>
          <p className="text-[10px] uppercase tracking-[0.4em] text-blue-500 font-black mt-1">CHALLENGE CORE</p>
        </div>
      </div>

      <nav className="flex-1 space-y-3 relative z-10">
        {menuItems.map((item) => {
          const Icon = item.icon;
          const isActive = currentView === item.id;
          return (
            <motion.button
              key={item.id}
              whileHover={{ x: 5 }}
              whileTap={{ scale: 0.98 }}
              onClick={() => setCurrentView(item.id)}
              className={`w-full group flex items-center gap-4 px-5 py-4 rounded-2xl transition-all duration-300 relative overflow-hidden ${
                isActive 
                  ? 'bg-blue-600 text-white shadow-2xl shadow-blue-600/20 active:scale-95' 
                  : 'text-slate-500 hover:text-slate-200 hover:bg-white/5'
              }`}
            >
              {isActive && (
                <motion.div 
                  layoutId="active-indicator"
                  className="absolute inset-0 bg-gradient-to-r from-blue-600 to-indigo-600 -z-10"
                />
              )}
              <Icon size={22} className={`${isActive ? 'animate-pulse text-white' : 'group-hover:text-blue-500 transition-colors'}`} />
              <span className="font-black text-xs uppercase tracking-widest">{item.label}</span>
              {isActive && (
                <motion.div 
                   initial={{ opacity: 0, x: -10 }}
                   animate={{ opacity: 1, x: 0 }}
                   className="ml-auto"
                >
                  <Target size={14} className="text-white/50" />
                </motion.div>
              )}
            </motion.button>
          );
        })}
      </nav>

      <div className="mt-auto pt-10 space-y-6 relative z-10">
        <motion.div 
          whileHover={{ y: -5 }}
          className="glass-card p-6 bg-[#020617] border border-white/5 relative group overflow-hidden"
        >
          <div className="absolute -right-10 -bottom-10 w-24 h-24 bg-blue-600/5 blur-2xl group-hover:bg-blue-600/10 transition-all pointer-events-none" />
          <div className="flex justify-between items-start mb-6">
            <div className="space-y-1">
              <p className="text-[10px] uppercase tracking-[0.2em] text-slate-500 font-black">Reputation</p>
              <div className="flex items-center gap-2">
                <p className="text-4xl font-black text-white italic tracking-tighter">{points}</p>
                <Zap size={18} className="text-yellow-500 fill-yellow-500 animate-pulse" />
              </div>
            </div>
            <div className="text-right space-y-1">
              <p className="text-[10px] uppercase tracking-[0.2em] text-orange-500 font-black">Streak</p>
              <div className="flex items-center justify-end gap-2">
                <p className="text-xl font-black text-white">{streak}</p>
                <div className="w-6 h-6 rounded-lg bg-orange-600/20 flex items-center justify-center text-orange-500 shadow-lg border border-orange-500/10">
                  <Flame size={12} className="fill-orange-500" />
                </div>
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <div className="flex justify-between text-[8px] font-black uppercase tracking-widest text-slate-500">
              <span>Next Milestone</span>
              <span>{Math.min((streak / 30) * 100, 100).toFixed(0)}%</span>
            </div>
            <div className="w-full bg-white/5 rounded-full h-1.5 overflow-hidden ring-1 ring-white/5">
              <motion.div 
                initial={{ width: 0 }}
                animate={{ width: `${Math.min((streak / 30) * 100, 100)}%` }}
                transition={{ duration: 1.5, ease: "easeOut" }}
                className="bg-gradient-to-r from-blue-500 via-indigo-500 to-purple-500 h-full rounded-full shadow-[0_0_10px_rgba(59,130,246,0.3)]"
              />
            </div>
          </div>
        </motion.div>

        <motion.button
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
          onClick={() => setDarkMode(!darkMode)}
          className="w-full flex items-center justify-between px-6 py-5 rounded-3xl bg-white/5 hover:bg-white/10 border border-white/5 border-dashed transition-all group overflow-hidden"
        >
          <div className="flex items-center gap-4 relative z-10">
            <div className={`p-2 rounded-xl flex items-center justify-center transition-colors ${darkMode ? 'bg-blue-600/10 text-blue-400' : 'bg-yellow-500/10 text-yellow-500'}`}>
              {darkMode ? <Moon size={20} /> : <Sun size={20} />}
            </div>
            <span className="text-xs font-black uppercase tracking-widest text-slate-400 group-hover:text-white transition-colors">{darkMode ? 'Dark' : 'Light'} CORE</span>
          </div>
          <div className={`w-10 h-5 rounded-full relative p-0.5 transition-colors ${darkMode ? 'bg-blue-600' : 'bg-slate-700'}`}>
            <motion.div 
               animate={{ x: darkMode ? 20 : 0 }}
               className="w-4 h-4 rounded-full bg-white shadow-xl" 
            />
          </div>
        </motion.button>
      </div>
    </aside>
  );
};

export default Sidebar;
